export const integrationExchange = pgTable("integration_exchange", {
	id: uuid().defaultRandom().primaryKey().notNull(),
	organizationId: uuid("organization_id"),
	requestId: uuid("request_id"),
	correlationId: uuid("correlation_id"),
	commandId: uuid("command_id"),
	integration: text().notNull(),
	direction: text().notNull(),
	operation: text().notNull(),
	request: jsonb().default({}).notNull(),
	response: jsonb(),
	status: text().default('pending').notNull(),
	httpStatus: integer("http_status"),
	durationMs: integer("duration_ms"),
	errorDetail: text("error_detail"),
	createdAt: timestamp("created_at", { withTimezone: true, mode: 'string' }).defaultNow().notNull(),
	updatedAt: timestamp("updated_at", { withTimezone: true, mode: 'string' }),
	version: integer().default(1).notNull(),
}, (table) => [
	index("integration_exchange_created_idx").using("btree", table.createdAt.asc().nullsLast().op("timestamptz_ops")),
	index("integration_exchange_request_idx").using("btree", table.requestId.asc().nullsLast().op("timestamptz_ops"), table.createdAt.desc().nullsFirst().op("timestamptz_ops")),
	index("integration_exchange_scope_idx").using("btree", table.organizationId.asc().nullsLast().op("timestamptz_ops"), table.integration.asc().nullsLast().op("text_ops"), table.createdAt.desc().nullsFirst().op("text_ops")),
	foreignKey({
			columns: [table.commandId],
			foreignColumns: [command.id],
			name: "integration_exchange_command_id_fkey"
		}),
	foreignKey({
			columns: [table.organizationId],
			foreignColumns: [organization.id],
			name: "integration_exchange_organization_id_fkey"
		}),
	pgPolicy("integration_exchange_tenant_isolation", { as: "permissive", for: "all", to: ["public"], using: sql`(organization_id = (NULLIF(current_setting('app.organization_id'::text, true), ''::text))::uuid)`, withCheck: sql`(organization_id = (NULLIF(current_setting('app.organization_id'::text, true), ''::text))::uuid)`  }),
	check("integration_exchange_direction_check", sql`direction = ANY (ARRAY['inbound'::text, 'outbound'::text])`),
	check("integration_exchange_duration_ms_check", sql`duration_ms >= 0`),
	check("integration_exchange_status_check", sql`status = ANY (ARRAY['pending'::text, 'success'::text, 'client_error'::text, 'server_error'::text, 'timeout'::text, 'rejected'::text, 'unknown'::text])`),
]);
